#!/usr/bin/env python3
"""Independent exact verifier for the flip graph of the K_{3,3} associahedron.

The state and edge construction in this file is deliberately different from
``verify_k33_diameter.py``:

* states are generated recursively as graph search trees, by choosing a root
  and recursing on the connected components left after deleting that root;
* edges are generated by direct parent--child rotations of those trees;
* only after both constructions are complete is a search tree mapped to its
  collection of descendant sets and compared with the maximal-tubing census.

All graph operations, rotations, comparisons, and breadth-first searches use
exact finite data.  No random choices or floating-point arithmetic occur.
"""

from __future__ import annotations

import argparse
from collections import Counter, deque
from contextlib import redirect_stdout
from functools import lru_cache
from hashlib import sha256
import importlib.util
from io import StringIO
from itertools import product
import json
from pathlib import Path
from typing import Iterable


N = 6
FULL = (1 << N) - 1
OUTSIDE = -2
ROOT = -1
NAMES = ("p1", "p2", "p3", "q1", "q2", "q3")

# The graph is specified as nine individual undirected edges, rather than by
# the specialized connectedness predicate used by the tubing implementation.
EDGES = tuple((p, q) for p in range(3) for q in range(3, 6))
ADJ_MASK = [0] * N
for a, b in EDGES:
    ADJ_MASK[a] |= 1 << b
    ADJ_MASK[b] |= 1 << a
ADJ_MASK = tuple(ADJ_MASK)


def bits(mask: int) -> tuple[int, ...]:
    """Vertices of ``mask`` in increasing label order."""
    return tuple(v for v in range(N) if mask & (1 << v))


def components(mask: int) -> tuple[int, ...]:
    """Connected-component masks of an induced subgraph, computed by DFS."""
    unseen = mask
    answer: list[int] = []
    while unseen:
        seed_bit = unseen & -unseen
        unseen ^= seed_bit
        component = seed_bit
        stack = [seed_bit.bit_length() - 1]
        while stack:
            vertex = stack.pop()
            frontier = ADJ_MASK[vertex] & unseen
            while frontier:
                next_bit = frontier & -frontier
                frontier ^= next_bit
                unseen ^= next_bit
                component |= next_bit
                stack.append(next_bit.bit_length() - 1)
        answer.append(component)
    return tuple(sorted(answer))


def is_connected(mask: int) -> bool:
    return bool(mask) and len(components(mask)) == 1


def parent_root(parent: tuple[int, ...], mask: int = FULL) -> int:
    roots = [v for v in bits(mask) if parent[v] == ROOT]
    if len(roots) != 1:
        raise AssertionError(f"expected one root on mask {mask}, got {roots}")
    return roots[0]


@lru_cache(maxsize=None)
def search_trees(mask: int) -> tuple[tuple[int, ...], ...]:
    """Enumerate every search tree on a connected induced vertex set.

    A graph search tree is defined recursively: choose its root ``r`` and make
    the roots of search trees on the components of ``G[mask - r]`` the
    children of ``r``.  The recursion is exhaustive by this definition, and
    its branches are disjoint because the root and component restrictions are
    recoverable from the resulting parent vector.
    """
    if not is_connected(mask):
        raise AssertionError(f"search_trees called on disconnected mask {mask}")
    output: list[tuple[int, ...]] = []
    for root in bits(mask):
        component_masks = components(mask ^ (1 << root))
        component_families = [search_trees(part) for part in component_masks]
        choices: Iterable[tuple[tuple[int, ...], ...]]
        choices = product(*component_families) if component_families else [()]
        for chosen_subtrees in choices:
            parent = [OUTSIDE] * N
            parent[root] = ROOT
            for part, subtree in zip(component_masks, chosen_subtrees):
                subtree_root = parent_root(subtree, part)
                for vertex in bits(part):
                    parent[vertex] = root if vertex == subtree_root else subtree[vertex]
            output.append(tuple(parent))
    if len(set(output)) != len(output):
        raise AssertionError(f"duplicate recursive search tree on mask {mask}")
    return tuple(sorted(output))


def descendant_masks(parent: tuple[int, ...]) -> tuple[int, ...]:
    """Return the descendant vertex set of each labelled tree node."""
    descendants = [0] * N
    for leafward_vertex in range(N):
        current = leafward_vertex
        seen: set[int] = set()
        while current != ROOT:
            if current in seen or not 0 <= current < N:
                raise AssertionError(f"invalid parent vector {parent}")
            seen.add(current)
            descendants[current] |= 1 << leafward_vertex
            current = parent[current]
    return tuple(descendants)


def validate_search_tree(parent: tuple[int, ...]) -> None:
    """Check the local recursive search-tree condition at every node."""
    if len(parent) != N or any(value == OUTSIDE for value in parent):
        raise AssertionError(f"not a full parent vector: {parent}")
    root = parent_root(parent)
    descendants = descendant_masks(parent)
    if descendants[root] != FULL:
        raise AssertionError("the root does not contain all vertices")
    for vertex in range(N):
        subtree = descendants[vertex]
        if not is_connected(subtree):
            raise AssertionError(f"disconnected descendant set at {vertex}: {subtree}")
        child_parts = tuple(
            sorted(descendants[child] for child in range(N) if parent[child] == vertex)
        )
        required_parts = components(subtree ^ (1 << vertex))
        if child_parts != required_parts:
            raise AssertionError(
                f"recursive component failure at {vertex}: {child_parts} != {required_parts}"
            )


def tubing_of_tree(parent: tuple[int, ...]) -> tuple[int, ...]:
    """Canonical maximal tubing: all six descendant masks, sorted."""
    return tuple(sorted(descendant_masks(parent)))


def rotate(parent: tuple[int, ...], upper: int, lower: int) -> tuple[int, ...]:
    """Rotate child ``lower`` above its parent ``upper`` directly.

    After the swap, an old child-subtree of ``lower`` moves below ``upper``
    precisely when that subtree contains a graph neighbor of ``upper``.  This
    is the direct graph-search-tree rotation rule: those and only those
    components join the component containing ``upper`` after deleting
    ``lower`` from the old ``upper`` subtree.
    """
    if parent[lower] != upper:
        raise AssertionError("rotation requested on a non-tree edge")
    old_descendants = descendant_masks(parent)
    old_grandparent = parent[upper]
    result = list(parent)
    for child in range(N):
        if parent[child] == lower and ADJ_MASK[upper] & old_descendants[child]:
            result[child] = upper
    result[lower] = old_grandparent
    result[upper] = lower
    rotated = tuple(result)
    validate_search_tree(rotated)
    return rotated


def state_bytes(state: tuple[int, ...]) -> bytes:
    # Every mask is in [1,63], so this is a fixed-length injective encoding.
    return bytes(state)


def state_hash(state: tuple[int, ...]) -> str:
    return sha256(state_bytes(state)).hexdigest()


def hash_state_sequence(states: Iterable[tuple[int, ...]]) -> str:
    payload = b"".join(state_bytes(state) for state in states)
    return sha256(payload).hexdigest()


def hash_edges(edges: Iterable[tuple[int, int]]) -> str:
    payload = "\n".join(f"{a},{b}" for a, b in edges).encode("ascii")
    return sha256(payload).hexdigest()


def load_tubing_reference(path: Path):
    """Execute the pre-existing implementation only after our census exists."""
    spec = importlib.util.spec_from_file_location("tubing_reference", path)
    if spec is None or spec.loader is None:
        raise AssertionError(f"cannot import {path}")
    module = importlib.util.module_from_spec(spec)
    with redirect_stdout(StringIO()):
        spec.loader.exec_module(module)
    return module


def bfs(adjacency: tuple[tuple[int, ...], ...], start: int, want_pred: bool = False):
    distances = [-1] * len(adjacency)
    predecessors = [-1] * len(adjacency) if want_pred else None
    distances[start] = 0
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for nxt in adjacency[current]:
            if distances[nxt] == -1:
                distances[nxt] = distances[current] + 1
                if predecessors is not None:
                    predecessors[nxt] = current
                queue.append(nxt)
    if -1 in distances:
        raise AssertionError(f"rotation graph disconnected from source {start}")
    return tuple(distances), None if predecessors is None else tuple(predecessors)


def named_tubing(state: tuple[int, ...]) -> list[list[str]]:
    return [[NAMES[v] for v in bits(mask)] for mask in state]


def build_result(project_dir: Path) -> dict:
    source_path = project_dir / "source.md"
    reference_path = project_dir / "evidence" / "verify_k33_diameter.py"

    # Independent state census and an intrinsic validation of every output.
    trees = search_trees(FULL)
    for tree in trees:
        validate_search_tree(tree)
    tree_by_state: dict[tuple[int, ...], tuple[int, ...]] = {}
    for tree in trees:
        state = tubing_of_tree(tree)
        if state in tree_by_state:
            raise AssertionError("two search trees mapped to the same descendant tubing")
        tree_by_state[state] = tree
    states = tuple(sorted(tree_by_state))
    state_index = {state: i for i, state in enumerate(states)}

    root_histogram = Counter(parent_root(tree) for tree in trees)
    if len(trees) != 552 or len(states) != 552:
        raise AssertionError(f"unexpected independent state census: {len(trees)}, {len(states)}")

    # Direct rotations.  Exactly five oriented rotations leave every full tree.
    directed_rotation: dict[tuple[int, int], tuple[int, int]] = {}
    undirected_edge_set: set[tuple[int, int]] = set()
    adjacency_sets = [set() for _ in states]
    for state, tree in tree_by_state.items():
        source = state_index[state]
        for lower in range(N):
            upper = tree[lower]
            if upper == ROOT:
                continue
            rotated_tree = rotate(tree, upper, lower)
            rotated_state = tubing_of_tree(rotated_tree)
            if rotated_tree not in trees:
                raise AssertionError("a direct rotation escaped the recursive census")
            if tree_by_state.get(rotated_state) != rotated_tree:
                raise AssertionError("rotated tree/state lookup mismatch")
            target = state_index[rotated_state]
            key = (source, target)
            if key in directed_rotation:
                raise AssertionError(f"two rotations produce the same directed edge {key}")
            directed_rotation[key] = (upper, lower)
            edge = (min(source, target), max(source, target))
            undirected_edge_set.add(edge)
            adjacency_sets[source].add(target)
    direct_edges = tuple(sorted(undirected_edge_set))
    adjacency = tuple(tuple(sorted(neighbors)) for neighbors in adjacency_sets)
    if len(directed_rotation) != 552 * 5:
        raise AssertionError("not exactly five oriented rotations per search tree")
    if len(direct_edges) != 1380:
        raise AssertionError(f"unexpected direct edge census: {len(direct_edges)}")
    if Counter(map(len, adjacency)) != Counter({5: 552}):
        raise AssertionError("direct rotation graph is not uniformly degree five")
    for source, target in directed_rotation:
        if (target, source) not in directed_rotation:
            raise AssertionError(f"rotation lacks its inverse: {(source, target)}")

    # Only now load and compare with the independent maximal-tubing program.
    reference = load_tubing_reference(reference_path)
    reference_states = tuple(sorted(tuple(state) for state in reference.TUBINGS))
    if states != reference_states:
        missing = sorted(set(reference_states) - set(states))
        extra = sorted(set(states) - set(reference_states))
        raise AssertionError(f"state-set mismatch: missing={missing[:2]}, extra={extra[:2]}")
    reference_edges_set: set[tuple[int, int]] = set()
    for old_i, neighbors in enumerate(reference.ADJACENCY):
        for old_j in neighbors:
            if old_i < old_j:
                a = state_index[tuple(reference.TUBINGS[old_i])]
                b = state_index[tuple(reference.TUBINGS[old_j])]
                reference_edges_set.add((min(a, b), max(a, b)))
    reference_edges = tuple(sorted(reference_edges_set))
    if direct_edges != reference_edges:
        missing = sorted(set(reference_edges) - set(direct_edges))
        extra = sorted(set(direct_edges) - set(reference_edges))
        raise AssertionError(f"edge-set mismatch: missing={missing[:2]}, extra={extra[:2]}")

    # Complete exact all-pairs BFS.  Each record commits separately to every
    # layer's canonical state membership and to the full ordered distance row.
    bfs_records: list[dict] = []
    eccentricities: list[int] = []
    distance_matrix_hasher = sha256()
    first_pair_at_distance: dict[int, tuple[int, int]] = {}
    for source in range(len(states)):
        distances, _ = bfs(adjacency, source)
        distance_matrix_hasher.update(bytes(distances))
        eccentricity = max(distances)
        eccentricities.append(eccentricity)
        first_pair_at_distance.setdefault(
            eccentricity, (source, distances.index(eccentricity))
        )
        layer_counts: list[int] = []
        layer_hashes: list[str] = []
        for distance in range(eccentricity + 1):
            members = tuple(states[i] for i, value in enumerate(distances) if value == distance)
            layer_counts.append(len(members))
            layer_hashes.append(hash_state_sequence(members))
        if sum(layer_counts) != len(states):
            raise AssertionError(f"BFS layers omit states at source {source}")
        bfs_records.append(
            {
                "source_index": source,
                "source_state_sha256": state_hash(states[source]),
                "eccentricity": eccentricity,
                "layer_counts": layer_counts,
                "layer_state_sequence_sha256": layer_hashes,
                "distance_row_sha256": sha256(bytes(distances)).hexdigest(),
            }
        )
    diameter = max(eccentricities)
    if diameter != 12:
        raise AssertionError(f"independent all-pairs diameter is {diameter}, not 12")

    witness_source, witness_target = first_pair_at_distance[diameter]
    witness_distances, predecessors = bfs(adjacency, witness_source, want_pred=True)
    assert predecessors is not None
    reverse_path = [witness_target]
    while reverse_path[-1] != witness_source:
        reverse_path.append(predecessors[reverse_path[-1]])
    witness_path = tuple(reversed(reverse_path))
    if len(witness_path) - 1 != diameter or witness_distances[witness_target] != diameter:
        raise AssertionError("invalid diametral witness reconstruction")
    witness_steps: list[dict] = []
    for position, index in enumerate(witness_path):
        tree = tree_by_state[states[index]]
        entry = {
            "position": position,
            "state_index": index,
            "state_sha256": state_hash(states[index]),
            "parent_vector": list(tree),
            "tubing_masks": list(states[index]),
            "tubing_named": named_tubing(states[index]),
        }
        if position + 1 < len(witness_path):
            target = witness_path[position + 1]
            upper, lower = directed_rotation[(index, target)]
            entry["next_rotation"] = {
                "old_parent": upper,
                "old_parent_name": NAMES[upper],
                "old_child": lower,
                "old_child_name": NAMES[lower],
                "target_state_index": target,
            }
        witness_steps.append(entry)

    source_digest = sha256(source_path.read_bytes()).hexdigest()
    reference_digest = sha256(reference_path.read_bytes()).hexdigest()
    own_digest = sha256(Path(__file__).read_bytes()).hexdigest()
    expected_source_digest = "ad57a7fcb9e8fd4626d17086a4c94e4e25059b2e75d86a8a294ec98015c3c5f1"
    if source_digest != expected_source_digest:
        raise AssertionError("frozen source.md hash changed")

    return {
        "artifact_status": "exact_candidate_evidence_not_mathematical_acceptance",
        "job_id": "win-00084-p01-research-9fb1caa274eb",
        "command": "python3 evidence/independent_search_tree_verifier.py --output evidence/independent_search_tree_run.json",
        "exactness": "integer finite enumeration and unweighted BFS; no randomness or floating point",
        "frozen_source_sha256": source_digest,
        "independent_verifier_sha256": own_digest,
        "comparison_verifier_sha256": reference_digest,
        "graph": {
            "name": "K_{3,3}",
            "vertex_order": list(NAMES),
            "edge_pairs_zero_based": [list(edge) for edge in EDGES],
        },
        "recursive_search_tree_census": {
            "definition": "choose each possible root and recurse on every induced component after root deletion",
            "full_tree_count": len(trees),
            "root_histogram_zero_based": {
                str(root): root_histogram[root] for root in sorted(root_histogram)
            },
            "distinct_descendant_tubing_count": len(states),
            "canonical_state_sequence_sha256": hash_state_sequence(states),
            "state_set_equals_bron_kerbosch_tubing_set": True,
            "canonical_states_masks": [list(state) for state in states],
        },
        "direct_rotation_graph": {
            "rule": "swap parent/child; move an old child-subtree of the promoted node under the demoted node iff it contains a graph neighbor of the demoted node",
            "oriented_rotation_count": len(directed_rotation),
            "undirected_edge_count": len(direct_edges),
            "degree_histogram": {
                str(degree): count for degree, count in sorted(Counter(map(len, adjacency)).items())
            },
            "canonical_edge_index_sequence_sha256": hash_edges(direct_edges),
            "edge_set_equals_ridge_exchange_tubing_edge_set": True,
        },
        "all_pairs_bfs": {
            "source_count": len(states),
            "target_count_per_source": len(states),
            "ordered_pair_count": len(states) ** 2,
            "all_sources_reach_all_states": True,
            "diameter": diameter,
            "eccentricity_histogram": {
                str(ecc): count for ecc, count in sorted(Counter(eccentricities).items())
            },
            "distance_matrix_row_major_sha256": distance_matrix_hasher.hexdigest(),
            "complete_layer_records": bfs_records,
        },
        "diametral_witness": {
            "source_index": witness_source,
            "target_index": witness_target,
            "bfs_distance": witness_distances[witness_target],
            "path_edge_count": len(witness_path) - 1,
            "path": witness_steps,
        },
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path)
    arguments = parser.parse_args()
    project_dir = Path(__file__).resolve().parent.parent
    result = build_result(project_dir)
    rendered = json.dumps(result, indent=2, sort_keys=True) + "\n"
    if arguments.output is None:
        print(rendered, end="")
    else:
        output = arguments.output
        if not output.is_absolute():
            output = project_dir / output
        if output.resolve().parent != (project_dir / "evidence").resolve():
            raise SystemExit("output must be a direct child of PROJECT_DIR/evidence")
        output.write_text(rendered, encoding="utf-8")


if __name__ == "__main__":
    main()
